"""vectorops: small collection of vector operations."""


def dotproduct(a, b):
    """Return the dot product of two equal-length sequences of numbers.

    a, b: iterables of ints or floats of the same length.
    """
    if len(a) != len(b):
        raise ValueError("inputs must have the same length")
    return sum(x * y for x, y in zip(a, b))

"""Witness tests for vectorops.dotproduct.

Run from the package source dir (/app/vectorops) so that the local
`vectorops/` package resolves ahead of any site-packages copy.
"""
from vectorops import dotproduct


def test_exact_spec_assertion():
    # The exact assertion from the task spec.
    assert 1 == dotproduct([1, 1], [0, 1])


def test_basic_dot_products():
    assert 0 == dotproduct([1, 0], [0, 1])
    assert 6 == dotproduct([1, 2, 3], [1, 1, 1])
    assert 32 == dotproduct([1, 2, 3], [4, 5, 6])  # 4+10+18


def test_floats():
    assert 1.0 == dotproduct([0.5, 0.5], [1.0, 1.0])


def test_empty():
    assert 0 == dotproduct([], [])


def test_length_mismatch_raises():
    raised = False
    try:
        dotproduct([1, 2], [1])
    except ValueError:
        raised = True
    assert raised, "expected ValueError on length mismatch"

